"""IMP2-17/18: generated bytes, explicit mapping and complete import coverage."""
import copy
import hashlib
from pathlib import Path
import tempfile
import unittest
import xml.etree.ElementTree as ET

from clxreg import export
from tests.test_ledger import Fx
from tests.test_units import ods, row, cell, p

H = '227733484a1851bc512f7ba3fef6dd78b6d0e5da'


def model():
    return {'schema': 'model/1', 'records': [
        {'id': 'CLX-REQ-0002', 'type': 'REQ', 'title': 'unknown', 'asserted_status': [{'status': 'DONE'}]},
        {'id': 'CLX-REQ-0001', 'type': 'REQ', 'title': 'a  b\tc\nd <e>'}],
        'derived': {'CLX-REQ-0002': {'verification': 'UNKNOWN', 'effective_status': 'UNKNOWN'},
                    'CLX-REQ-0001': {'verification': 'VERIFIED', 'effective_status': 'DONE'}},
        'findings': [], 'valid': True, 'examined': 2, 'rule_counts': {}}


class ViewTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.root = Path(self.tmp.name)

    def test_repeat_and_record_order_have_identical_bytes(self):
        original = model()
        reordered = copy.deepcopy(original)
        reordered['records'].reverse()
        one = export.tables(original, registry_commit=H)
        two = export.tables(reordered, registry_commit=H)
        self.assertEqual(export.tsv(one), export.tsv(two))
        self.assertEqual(export.fods(one), export.fods(two))
        self.assertEqual(export.fods(one), export.fods(one))
        self.assertEqual(original, model())
        self.assertIn(['registry_commit_role', 'reference baseline; clean-tree binding not asserted'], one['REGISTRY-METADATA'])
        digest = next(r[1] for r in one['REGISTRY-METADATA'] if r[0] == 'registry_records_sha256')
        self.assertEqual(len(digest), 64)
        changed = model()
        changed['records'][0]['title'] = 'different saved registry content'
        changed_meta = export.tables(changed, registry_commit=H)['REGISTRY-METADATA']
        self.assertNotEqual(digest, next(r[1] for r in changed_meta if r[0] == 'registry_records_sha256'))

    def test_fods_xml_uses_string_cells_and_preserves_literal_whitespace(self):
        data = export.fods(export.tables(model(), registry_commit=H))
        root = ET.fromstring(data)
        self.assertEqual(root.tag, '{'+export.OFFICE+'}document')
        self.assertTrue(root.findall('.//{'+export.TEXT+'}s'))
        self.assertTrue(root.findall('.//{'+export.TEXT+'}tab'))
        self.assertTrue(root.findall('.//{'+export.TEXT+'}line-break'))
        self.assertNotIn(b'table:formula', data)
        self.assertIn(b'&lt;e&gt;', data)

    def test_formula_like_values_are_literal_and_carriage_return_is_preserved(self):
        data = export.fods({'literal': [['=SUM(A1:A2)', 'a\rb']]})
        parsed = ET.fromstring(data)
        cells = parsed.findall('.//{'+export.TABLE+'}table-cell')
        self.assertTrue(all(c.get('{'+export.OFFICE+'}value-type') == 'string' for c in cells))
        self.assertEqual(cells[0].find('{'+export.TEXT+'}p').text, '=SUM(A1:A2)')
        self.assertEqual(cells[1].find('{'+export.TEXT+'}p').text, 'a\rb')
        self.assertNotIn(b'formula=', data)
        with self.assertRaises(export.ExportError):
            export.fods({'bad': [['nul\x00char']]})

    def test_explicit_ods_row_mapping_input_hash_is_unchanged(self):
        path = self.root / 'source.ods'
        path.write_bytes(ods({'Plan': row(cell(p('RT1')), cell(p('DONE')))}))
        before = path.read_bytes()
        mapping = {'schema': 'clx.roadmap-mapping/1', 'rows': [{'record': 'CLX-REQ-0001', 'sheet': 'Plan', 'row_id': 'RT1'}]}
        tables = export.tables(model(), registry_commit=H, mapping=mapping, ods_path=path)
        self.assertEqual(tables['REGISTRY-ROADMAP'][1][-3:], ['Plan', 'RT1', '1'])
        self.assertEqual(tables['REGISTRY-EXPORT-FINDINGS'], [['record', 'message', 'sheet', 'row_id']])
        self.assertEqual(path.read_bytes(), before)
        self.assertIn(['ODS sha256', hashlib.sha256(before).hexdigest()], tables['REGISTRY-METADATA'])

    def test_absent_and_ambiguous_ods_rows_are_named_without_guessing(self):
        path = self.root / 'source.ods'
        path.write_bytes(ods({'Plan': row(cell(p('RT1'))) + row(cell(p('RT1')))}))
        mapping = {'schema': 'clx.roadmap-mapping/1', 'rows': [
            {'record': 'CLX-REQ-0001', 'sheet': 'Plan', 'row_id': 'RT1'},
            {'record': 'CLX-REQ-0002', 'sheet': 'Plan', 'row_id': 'RT2'}]}
        tables = export.tables(model(), registry_commit=H, mapping=mapping, ods_path=path)
        self.assertEqual([r[1] for r in tables['REGISTRY-EXPORT-FINDINGS'][1:]], ['ODS row id is ambiguous', 'ODS row not found'])
        self.assertEqual([r[-1] for r in tables['REGISTRY-ROADMAP'][1:]], ['', ''])

    def test_claim_done_is_displayed_beside_unknown_with_drift(self):
        r = export.tables(model(), registry_commit=H)['REGISTRY-ROADMAP'][2]
        self.assertEqual(r[3:7], ['UNKNOWN', 'UNKNOWN', 'DONE', 'CLAIM_DIFFERS'])

    def test_refuses_overwrite_for_both_formats(self):
        for extension in ('tsv', 'fods'):
            path = self.root / ('view.'+extension)
            export.write(path, model(), registry_commit=H)
            before = path.read_bytes()
            with self.assertRaises(FileExistsError):
                export.write(path, model(), registry_commit=H)
            self.assertEqual(path.read_bytes(), before)

    def test_bad_model_commit_or_mapping_is_not_silently_exported(self):
        for bad in ('', '2277334', None):
            with self.assertRaises(export.ExportError):
                export.tables(model(), registry_commit=bad)
        with self.assertRaises(export.ExportError):
            export.tables({'schema': 'model/2'}, registry_commit=H)
        with self.assertRaises(export.ExportError):
            export.tables({**model(), 'schema': 'model/2'}, registry_commit=H)
        with self.assertRaises(export.ExportError):
            export.tables(model(), registry_commit=H, mapping={'schema': 'bad'})
        with self.assertRaises(export.ExportError):
            export.tables(model(), registry_commit=H, mapping={'schema': 'clx.roadmap-mapping/1', 'rows': []})


class CoverageTests(Fx):
    def test_every_disposition_occurrence_has_summary_and_literal_detail(self):
        led = self.build()
        tables = export.tables(model(), registry_commit=H, import_ledger=led)
        summary = tables['REGISTRY-COVERAGE-OF-IMPORT'][1:]
        detail = tables['REGISTRY-IMPORT-OCCURRENCES'][1:]
        self.assertEqual(sum(int(r[-1]) for r in summary), len(led['entries']))
        self.assertEqual(len(detail), len(led['entries']))
        self.assertEqual(sorted(r[5] for r in detail), sorted(e['text'] for e in led['entries']))
        self.assertIn('AMBIGUOUS', {r[2] for r in summary})
        self.assertIn('RANGE_NOT_EXPANDED', {r[2] for r in summary})
        self.assertTrue(next(r[1] for r in tables['REGISTRY-METADATA'] if r[0] == 'import_ledger_sha256'))

    def test_ledger_changes_alter_the_view_and_summary_is_checked(self):
        before = self.build()
        (self.ws / 'a.md').write_bytes(b'RT1 RT1 RT1 RT1\n')
        self.src['sources'][0]['versions'][0].update(sha256=hashlib.sha256(b'RT1 RT1 RT1 RT1\n').hexdigest(), bytes=16)
        # Build a valid new ledger from the changed explicitly pinned source.
        self.src['sources'][0]['versions'][0]['bytes'] = len((self.ws / 'a.md').read_bytes())
        after = self.build()
        self.assertNotEqual(export.tsv(export.tables(model(), registry_commit=H, import_ledger=before)), export.tsv(export.tables(model(), registry_commit=H, import_ledger=after)))
        after['summary']['entries'] += 1
        with self.assertRaises(export.ExportError):
            export.tables(model(), registry_commit=H, import_ledger=after)


if __name__ == '__main__':
    unittest.main()
